typescript\": \"^5.9.2\"\n  },\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"packageManager\": \"pnpm@11.7.0\",\n  \"dependencies\": {\n    \"ignore\": \"^7.0.9\"\n  }\n}\n"
